/* A self-contained route from local inertial physics to the scene metrics.
 * MathML and SVG only; generated lazily when the notebook is opened. */
const I=s=>'<mi>'+s+'</mi>',N=s=>'<mn>'+s+'</mn>',O=s=>'<mo>'+s+'</mo>',T=s=>'<mtext>'+s+'</mtext>';
const R=(...x)=>'<mrow>'+x.join('')+'</mrow>',S=(a,b)=>'<msub>'+a+b+'</msub>',P=(a,b)=>'<msup>'+a+b+'</msup>',F=(a,b)=>'<mfrac>'+a+b+'</mfrac>';
const Q=a=>'<msqrt><mrow>'+a+'</mrow></msqrt>',B=a=>R(O('('),R(a),O(')')),V=s=>'<mi mathvariant="bold">'+s+'</mi>',sq=a=>P(a,N(2));
const trig2=(name,arg)=>R(P('<mi mathvariant="normal">'+name+'</mi>',N(2)),arg);
const D=a=>R(I('d'),a);
const row=(...lines)=>'<mtable columnalign="left" rowspacing="0.7em">'+lines.map(x=>'<mtr><mtd>'+x+'</mtd></mtr>').join('')+'</mtable>';
const eq=(x,label)=>'<div class="equation" aria-label="'+label+'"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block">'+x+'</math></div>';
const part=(id,title,body,open=false)=>'<details class="math-section" id="rel-'+id+'"'+(open?' open':'')+'><summary><span class="math-index">'+id+'</span><span>'+title+'</span><span class="math-chevron" aria-hidden="true">＋</span></summary><div class="math-section-body">'+body+'</div></details>';
const link=(url,label)=>'<a href="'+url+'" target="_blank" rel="noopener noreferrer">'+label+' ↗</a>';
const c=I('c'),t=I('t'),tau=I('τ'),x=I('x'),r=I('r'),G=I('G'),M=I('M'),a=I('a'),v=I('v'),gamma=I('γ'),beta=I('β'),phi=I('Φ'),theta=I('θ'),az=I('φ'),rg=S(r,I('g')),rs=S(r,I('s'));
const X=i=>P(x,I(i)),U=i=>P(I('u'),I(i)),g=(i,j)=>S(I('g'),R(I(i),I(j))),ginv=(i,j)=>P(I('g'),R(I(i),I(j))),C=(i,j,k)=>'<msubsup>'+I('Γ')+R(I(j),I(k))+I(i)+'</msubsup>',Rm=(i,j,k,l)=>'<msubsup>'+I('R')+R(I(j),I(k),I(l))+I(i)+'</msubsup>';
const fig=(svg,caption)=>'<figure class="relativity-figure">'+svg+'<figcaption>'+caption+'</figcaption></figure>';
const svg=(id,title,desc,body)=>'<svg class="relativity-diagram" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 310" role="img" aria-labelledby="'+id+'-title '+id+'-desc"><title id="'+id+'-title">'+title+'</title><desc id="'+id+'-desc">'+desc+'</desc><rect width="720" height="310" rx="8" fill="#03080e"/><g font-family="DejaVu Sans,sans-serif" font-size="13" fill="#c2d8e8">'+body+'</g></svg>';

function coneDiagram(){return svg('rel-cone','One light cone, two inertial frames','Time runs upward and space rightward. Light is at forty-five degrees. A moving frame has a tilted time axis and a differently tilted simultaneity axis; both retain the same light cone.',
 '<defs><marker id="rel-cone-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#8ab9d9"/></marker></defs>'+
 '<path d="M180 245L20 85H340Z" fill="#5fc5f213"/><path d="M20 85L180 245L340 85" fill="none" stroke="#7fd8fa" stroke-width="2"/>'+
 '<path d="M28 245H362 M180 272V22" fill="none" stroke="#63849f" stroke-width="1.6" marker-end="url(#rel-cone-arrow)"/><text x="367" y="250">x</text><text x="187" y="28">ct</text>'+
 '<path d="M180 245L273 59 M180 245L355 157" fill="none" stroke="#e1b977" stroke-width="2"/><text x="278" y="58" fill="#edc98e">ct′</text><text x="350" y="145" fill="#edc98e">x′</text>'+
 '<circle cx="180" cy="245" r="4" fill="#edf7ff"/><text x="164" y="265">O</text><text x="64" y="75" fill="#7fd8fa">light</text><text x="184" y="97" fill="#89bad3">future</text>'+
 '<path d="M390 36V274" stroke="#243c50"/><text x="414" y="57" fill="#edf7ff" font-size="17">The cone is invariant.</text><text x="414" y="90">A boost changes the coordinate axes,</text><text x="414" y="111">not which signals can reach an event.</text>'+
 '<text x="414" y="151" fill="#edc98e">ct′ axis: the moving origin</text><text x="414" y="174">x′ axis: events simultaneous in S′</text><text x="414" y="216">Shown: v = 0.5c.</text><text x="414" y="239">A Lorentz boost is not an ordinary</text><text x="414" y="260">Euclidean rotation of the diagram.</text>');}
function clockDiagram(){return svg('rel-clocks','Rate and accumulated clock difference','Two columns compare ten seconds of distant reference time with five point six milliseconds onboard at a fixed rate ratio of eighteen hundred. The vertical drawing coordinate is reference time for both columns.',
 '<text x="155" y="38" text-anchor="middle" fill="#edf7ff" font-size="16">Distant reference</text><text x="395" y="38" text-anchor="middle" fill="#edf7ff" font-size="16">Onboard clock</text>'+
 '<path d="M155 228V88 M395 228V88" stroke="#8ccdf1" stroke-width="3"/><path d="M115 88H435 M115 228H435" stroke="#36546c" stroke-dasharray="4 6"/><circle cx="155" cy="88" r="5" fill="#b9e6ff"/><circle cx="395" cy="88" r="5" fill="#e7c17d"/>'+
 '<text x="155" y="72" text-anchor="middle" fill="#b9e6ff">10 s</text><text x="395" y="72" text-anchor="middle" fill="#e7c17d">5.6 ms</text><text x="155" y="252" text-anchor="middle">0 s</text><text x="395" y="252" text-anchor="middle">0 s</text>'+
 '<path d="M171 159H375" stroke="#547c9c"/><text x="275" y="145" text-anchor="middle" fill="#d9edfb">dt / dτ = 1,800</text>'+
 '<path d="M476 46V262" stroke="#243c50"/><text x="498" y="88" fill="#edf7ff" font-size="16">Difference gained</text><text x="498" y="123" fill="#e7c17d" font-size="23">≈ 9.994 s</text><text x="498" y="161">One onboard second</text><text x="498" y="182">corresponds to 30 min</text><text x="498" y="203">on the distant clock.</text>'+
 '<text x="360" y="292" text-anchor="middle" fill="#7e9cb4" font-size="11">Drawing height follows reference time; it is not a scale of proper time.</text>');}
function tidesDiagram(){return svg('rel-tides','Curvature changes the separation of neighboring free-fall paths','Two neighboring geodesics separate as time advances. A small highlighted region is locally inertial, but that local choice cannot remove the relative acceleration of neighboring trajectories.',
 '<defs><marker id="rel-tides-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#8ab9d9"/></marker></defs>'+
 '<path d="M62 260V42" stroke="#63849f" stroke-width="1.5" marker-end="url(#rel-tides-arrow)"/><text x="47" y="32">ct</text>'+
 '<path d="M151 255C151 197 140 117 113 53 M216 255C216 197 227 117 254 53" fill="none" stroke="#a9dcf9" stroke-width="2.7"/>'+
 '<path d="M151 239H216 M119 68H248" stroke="#e2ba79" stroke-width="1.6"/><text x="181" y="227" text-anchor="middle" fill="#e2ba79">ξ₀</text><text x="181" y="58" text-anchor="middle" fill="#e2ba79">ξ(τ)</text>'+
 '<rect x="122" y="153" width="58" height="56" rx="9" fill="#72cdf31a" stroke="#72cdf3"/><path d="M144 153L153 209" stroke="#edf7ff" stroke-dasharray="4 4"/>'+
 '<path d="M180 178C253 174 296 156 352 156" fill="none" stroke="#72cdf3" stroke-width="1.3"/><circle cx="180" cy="178" r="2.5" fill="#72cdf3"/>'+
 '<text x="376" y="66" fill="#edf7ff" font-size="17">Local straightness</text><text x="376" y="96">Free fall follows a geodesic.</text><text x="376" y="117">A freely falling frame removes Γ</text><text x="376" y="138">at an event, not the tidal curvature.</text>'+
 '<text x="376" y="188" fill="#e2ba79">Curvature is a relative effect.</text><text x="376" y="215">The Riemann tensor determines</text><text x="376" y="236">how neighboring free-fall paths</text><text x="376" y="257">converge, stretch, or shear.</text>');}

export function renderRelativityGuide(container){
 const minus=O('−'),plus=O('+'),equal=O('='),mu=I('μ'),nu=I('ν'),alpha=I('α'),lambda=I('λ'),E=I('E'),mass=I('m'),p=V('p'),vel=V('v'),f=R(N(1),minus,F(rs,r)),Sigma=I('Σ'),Delta=I('Δ');
 const interval=R(sq(D(I('s'))),equal,minus,sq(c),sq(D(t)),plus,sq(D(x)),plus,sq(D(I('y'))),plus,sq(D(I('z'))));
 const deriv2=(q,by)=>F(R(P(I('d'),N(2)),q),R(I('d'),sq(by)));
 const geom=R(g('μ','ν'),D(X('μ')),D(X('ν')));
 const kerr=row(
  R(sq(D(I('s'))),equal,minus,B(R(N(1),minus,F(R(N(2),rg,r),Sigma))),sq(c),sq(D(t)),minus,F(R(N(4),rg,a,r,trig2('sin',theta)),Sigma),c,D(t),D(az)),
  R(plus,F(Sigma,Delta),sq(D(r)),plus,Sigma,sq(D(theta)),plus,B(R(sq(r),plus,sq(a),plus,F(R(N(2),rg,sq(a),r,trig2('sin',theta)),Sigma))),trig2('sin',theta),sq(D(az)))
 );
 const shape=R(I('f'),B(S(r,I('s'))),equal,F(R(I('tanh'),B(R(I('σ'),B(R(S(r,I('s')),plus,I('R'))))),minus,I('tanh'),B(R(I('σ'),B(R(S(r,I('s')),minus,I('R')))))),R(N(2),I('tanh'),B(R(I('σ'),I('R'))))));
 container.innerHTML='<div class="math-guide relativity-guide"><p class="relativity-lead">Start with a clock and a light signal. Build an invariant interval, let its geometry vary, then follow that geometry to black holes, warp fields, and wormholes.</p>'+
 '<nav class="relativity-roadmap" aria-label="Relativity learning path">'+[['01','Events & light'],['02','Clocks & frames'],['04','Local gravity'],['06','Curvature'],['07','Field equations'],['09','Scene metrics']].map(([id,label])=>'<button data-relativity-section="rel-'+id+'"><span>'+id+'</span>'+label+'</button>').join('')+'</nav>'+
 '<div class="math-note"><strong>Conventions.</strong> Metric signature (−,+,+,+); x⁰ = ct; Greek indices run 0–3 and Latin spatial indices 1–3. Repeated upper/lower indices are summed. c is the local vacuum light speed, G the gravitational constant, τ proper time, and t a chosen coordinate time. SI units are retained unless explicitly stated.</div>'+
 part('01','Events, light cones, and Lorentz transformations',
 '<p>An event is a location and a time. In an inertial laboratory, a freely moving body has constant velocity. Special relativity combines the equivalence of inertial frames with the experimentally supported fact that all such observers measure the same local vacuum light speed c. Space and time therefore transform together.</p>'+eq(interval,'Minkowski interval with minus-plus-plus-plus signature')+
 '<p>The invariant interval classifies separations: timelike (ds² &lt; 0), null (ds² = 0), or spacelike (ds² &gt; 0). Massive observers trace timelike worldlines; light follows null paths. Timelike or null future-directed paths remain inside or on the light cone. A spacelike-separated event cannot be reached by a local signal at or below c.</p>'+fig(coneDiagram(),'Equal plotting scales for x and ct make light rays 45°. The primed axes show a boost, not a physical deformation of spacetime.')+
 '<p>Homogeneity makes the transformation between inertial coordinates linear. Requiring the light cone and interval to agree, and demanding the identity at v = 0, fixes a boost along x:</p>'+eq(row(R(P(x,O('′')),equal,gamma,B(R(x,minus,v,t))),R(P(t,O('′')),equal,gamma,B(R(t,minus,F(R(v,x),sq(c))))),R(gamma,equal,F(N(1),Q(R(N(1),minus,sq(beta)))),O(','),T('  β = v/c;   y′ = y;   z′ = z'))),'Lorentz boost and Lorentz factor')+
 '<p>The inverse replaces v by −v. In matrix form ΛᵀηΛ = η, with η = diag(−1,1,1,1). The Galilean transformation is the low-speed limit, not an independent rule to apply near c.</p>',true)+
 part('02','What a clock measures',
 '<p>Proper time is the time recorded by a clock traveling along its own timelike worldline. Substituting its spatial velocity into the interval gives:</p>'+eq(row(R(D(tau),equal,Q(R(N(1),minus,F(sq(v),sq(c)))),D(t),equal,F(D(t),gamma)),R(tau,equal,R(O('∫'),Q(R(N(1),minus,F(sq(v),sq(c)))),D(t)))),'Proper time along a timelike path in an inertial frame')+
 '<p>Thus a moving clock accumulates less proper time between specified events than the inertial clock connecting them. The comparison depends on the entire path. Acceleration changes the path and the relation between frames; it is not a universal extra instantaneous clock-slowing multiplier.</p>'+eq(row(R(S(I('L'),T('moving')),equal,F(S(I('L'),N(0)),gamma)),R(P(I('u'),O('′')),equal,F(R(I('u'),minus,v),R(N(1),minus,F(R(I('u'),v),sq(c)))))),'Length contraction and one-dimensional velocity transformation')+
 '<p>Length contraction compares endpoint positions simultaneous in the measuring frame; L₀ is the object’s rest length. Relativity of simultaneity follows from the vx/c² term in t′. These are distinct measurement procedures, not physical compression caused by looking at an object. Velocity addition keeps any local sublight motion below c.</p>'+
 '<h4>Rate is not accumulated difference</h4>'+eq(row(R(I('q'),equal,F(D(t),D(tau))),R(I('Δ'),T('clock'),equal,O('∫'),B(R(N(1),minus,F(N(1),I('q')))),D(t))),'Clock-rate ratio and accumulated distant-minus-local time difference')+
 '<p>At a fixed q = 1,800, one onboard second corresponds to 30 distant minutes. During ten distant seconds, the onboard clock advances only 10/1,800 s ≈ 5.6 ms; the difference grows by about 9.994 s. A huge ratio does not make the accumulated difference grow faster than the elapsed reference time. The reference-time convention must be stated before comparing any clocks.</p>'+fig(clockDiagram(),'A constant-rate example. The same ratio can arise from a chosen gravitational comparison or from motion; neither is a new rule for advancing scene dynamics.'))+
 part('03','Four-vectors, energy, and momentum',
 '<p>A four-vector transforms with the Lorentz matrix. For a massive particle, differentiate the spacetime position with respect to proper time:</p>'+eq(row(R(U('μ'),equal,F(D(X('μ')),D(tau)),equal,gamma,B(R(c,O(','),vel))),R(S(I('u'),mu),U('μ'),equal,minus,sq(c)),R(P(I('p'),mu),equal,mass,U('μ'),equal,B(R(F(E,c),O(','),p))),R(sq(E),equal,sq(p),sq(c),plus,sq(mass),P(c,N(4)))),'Four-velocity, four-momentum, and mass-shell relation')+
 '<p>Here p² means the Euclidean squared magnitude of the spatial momentum. E = γmc² and p = γmv. At rest E₀ = mc²; at low speeds E − mc² ≈ mv²/2. A photon has zero invariant mass and E = c|p|, but has energy and momentum and responds to gravity.</p>'+
 '<p>Proper acceleration is the magnitude of a<sup>μ</sup> = du<sup>μ</sup>/dτ in flat spacetime; u·a = 0. For a straight burn, proper acceleration α and coordinate acceleration satisfy α = γ³ dv/dt. Finite sustained α approaches c asymptotically, rather than passing through it. Energy-momentum is locally conserved in interactions.</p>')+
 part('04','From free fall to a spacetime metric',
 '<p>General relativity begins with local physics: in a sufficiently small freely falling laboratory, nongravitational experiments recover special relativity. A supported observer feels proper acceleration; an ideal freely falling observer does not. Across a finite region, tidal effects remain.</p>'+eq(row(R(sq(D(I('s'))),equal,geom),R(D(tau),equal,F(Q(R(minus,geom)),c))),'General metric interval and proper time')+
 '<p>The symmetric metric g<sub>μν</sub>(x) determines clock readings, spatial measurements, and light cones. At any regular event, coordinates can be chosen so g = η and the first derivatives of g vanish there. That does not make the second derivatives, and hence curvature, vanish. Coordinate values and visible grid lines are not themselves invariant physical measurements.</p>'+
 '<p>A metric is a field on spacetime, not a surface sitting in an extra physical direction. The simulator’s raised sheets are illustrative coordinate diagrams. Curvature can exist even when a selected constant-time spatial slice is flat.</p>')+
 part('05','Parallel transport and the geodesic equation',
 '<p>Comparing vectors at neighboring events requires a connection. Requiring zero torsion and compatibility with the metric uniquely gives the Levi-Civita connection:</p>'+eq(R(C('μ','α','β'),equal,F(N(1),N(2)),ginv('μ','ν'),B(R(S(O('∂'),alpha),g('ν','β'),plus,S(O('∂'),I('β')),g('ν','α'),minus,S(O('∂'),nu),g('α','β')))),'Levi-Civita connection from the metric')+
 '<p>The covariant derivative adds the change of the coordinate basis to the ordinary derivative: ∇<sub>α</sub>V<sup>μ</sup> = ∂<sub>α</sub>V<sup>μ</sup> + Γ<sup>μ</sup><sub>αν</sub>V<sup>ν</sup>. Free motion transports its own tangent parallel to itself. Equivalently, vary the proper-time action −mc²∫dτ:</p>'+eq(R(deriv2(X('μ'),lambda),plus,C('μ','α','β'),F(D(X('α')),D(lambda)),F(D(X('β')),D(lambda)),equal,N(0)),'Affinely parameterized geodesic equation')+
 '<p>For massive free fall, λ may be proper time. For light, proper time is zero, so use another affine parameter and impose g<sub>μν</sub>k<sup>μ</sup>k<sup>ν</sup> = 0. Apparent bending depends on coordinates, but measured arrival directions and lensing between observers are physical. A geodesic’s spatial projection may be an orbit: its four-dimensional tangent is parallel-transported, not a fixed arrow in a global Euclidean plane.</p>')+
 part('06','Curvature and tides',
 '<p>A connection can be made zero at an event. Curvature measures what cannot be removed this way: transporting a vector around an infinitesimal closed loop need not return the same vector. We use the convention:</p>'+eq(row(R(Rm('ρ','σ','μ','ν'),equal,S(O('∂'),mu),C('ρ','ν','σ'),minus,S(O('∂'),nu),C('ρ','μ','σ')),R(plus,C('ρ','μ','λ'),C('λ','ν','σ'),minus,C('ρ','ν','λ'),C('λ','μ','σ'))),'Riemann curvature tensor convention')+
 '<p>Contracting indices gives R<sub>μν</sub> = R<sup>ρ</sup><sub>μρν</sub> and scalar curvature R = g<sup>μν</sup>R<sub>μν</sub>. R is a scalar here, not the bubble radius used later. The change in separation ξ between neighboring geodesics is:</p>'+eq(R(F(R(P(I('D'),N(2)),P(I('ξ'),mu)),R(I('d'),sq(tau))),equal,minus,Rm('μ','α','ν','β'),U('α'),P(I('ξ'),nu),U('β')),'Geodesic deviation with the stated Riemann convention')+
 fig(tidesDiagram(),'A coordinate sketch of tidal separation, not an embedding of four-dimensional spacetime. The small highlighted patch admits a locally inertial frame.')+
 '<p>Vacuum does not mean zero curvature. Around an isolated black hole, the Ricci tensor vanishes while the full Riemann tensor still produces tidal forces and lensing. Tidal stretching, not a drawing of a bent sheet alone, is the local test of gravity’s curvature.</p>')+
 part('07','What determines the metric?',
 '<p>The metric is dynamical. Varying the Einstein–Hilbert gravitational action together with the matter action gives:</p>'+eq(row(R(I('S'),equal,F(P(c,N(3)),R(N(16),I('π'),G)),O('∫'),B(R(I('R'),minus,N(2),I('Λ'))),Q(R(minus,I('g'))),P(I('d'),N(4)),x,plus,S(I('S'),T('matter'))),R(S(I('R'),R(mu,nu)),minus,F(N(1),N(2)),I('R'),g('μ','ν'),plus,I('Λ'),g('μ','ν'),equal,F(R(N(8),I('π'),G),P(c,N(4))),S(I('T'),R(mu,nu)))),'Einstein-Hilbert action and Einstein field equations')+
 '<p>Here g is the determinant of g<sub>μν</sub>; d⁴x uses x⁰ = ct. Λ is the cosmological constant. T<sub>μν</sub> contains energy density, momentum density, flux, and stress—including pressure, not just rest mass. Boundary terms must be handled when varying the action.</p>'+
 '<p>The contracted Bianchi identity gives ∇<sub>μ</sub>G<sup>μν</sup> = 0, consistent with local conservation ∇<sub>μ</sub>T<sup>μν</sup> = 0. This is not a guarantee of one globally conserved energy in every time-dependent spacetime. Given matter, initial data, and boundary conditions, solve these nonlinear equations for a metric; then solve geodesics in that geometry. Adding two known metrics generally does not produce another solution.</p>')+
 part('08','Recovering Newtonian gravity',
 '<p>For a nearly static weak field with slowly moving matter and negligible anisotropic stress, write the metric to first order in |Φ|/c²:</p>'+eq(row(R(sq(D(I('s'))),O('≈'),minus,B(R(N(1),plus,F(R(N(2),phi),sq(c)))),sq(c),sq(D(t)),plus,B(R(N(1),minus,F(R(N(2),phi),sq(c)))),sq(D(V('x')))),R(P(O('∇'),N(2)),phi,equal,N(4),I('π'),G,I('ρ'),O(','),T('   '),F(R(P(I('d'),N(2)),V('x')),R(I('d'),sq(t))),O('≈'),minus,O('∇'),phi)),'Weak-field metric, Poisson equation, and Newtonian motion')+
 '<p>In the slow-motion geodesic equation, Γ<sup>i</sup><sub>00</sub> ≈ ∂<sub>i</sub>Φ/c² gives d²x/dt² ≈ −∇Φ. The field equations reduce to Poisson’s equation for mass density ρ. For Φ = −GM/r this recovers inverse-square attraction and approximately Keplerian orbits.</p>'+
 '<p>Clock shifts first appear as dτ/dt ≈ 1 + Φ/c² − v²/(2c²). Light requires the spatial metric as well as the time coefficient: in the weak isolated-mass limit its total deflection is 4GM/(bc²), with b the impact parameter. A Newtonian force sketch alone misses half of that deflection.</p>')+
 part('09','Schwarzschild: clocks, horizons, and orbits',
 '<p>Outside a spherical source, impose vacuum and spherical symmetry. With r defined by sphere area 4πr², the static ansatz is ds² = −A(r)c²dt² + B(r)dr² + r²dΩ². The vacuum equations and asymptotic flatness give B = 1/A and A = 1 − r<sub>s</sub>/r:</p>'+eq(row(R(sq(D(I('s'))),equal,minus,B(f),sq(c),sq(D(t)),plus,F(sq(D(r)),f),plus,sq(r),B(R(sq(D(theta)),plus,trig2('sin',theta),sq(D(az))))),R(rs,equal,F(R(N(2),G,M),sq(c)),equal,N(2),rg)),'Schwarzschild exterior metric')+
 '<p>A stationary clock outside the horizon has dτ/dt = √(1 − r<sub>s</sub>/r), with t normalized to a stationary clock at infinity. For local speed v measured by a stationary observer at that radius, gravity and the local Lorentz factor combine:</p>'+eq(R(F(D(tau),D(t)),equal,Q(R(N(1),minus,F(rs,r))),Q(R(N(1),minus,F(sq(S(v,T('local'))),sq(c))))),'Exterior Schwarzschild clock comparison')+
 '<p>The ratio dt/dτ diverges as a stationary clock approaches r<sub>s</sub>, but hovering requires unbounded proper acceleration. No stationary observer exists at the horizon. For radial fall from rest at infinity, dτ/dt = 1 − r<sub>s</sub>/r outside: the infaller crosses in finite proper time, while Schwarzschild coordinate time diverges. The apparent freeze is a distant-coordinate and received-signal effect, not the stopping of the infaller’s own clock.</p>'+
 '<p>Circular timelike geodesics require r &gt; 3r<sub>g</sub>, and are stable only for r ≥ 6r<sub>g</sub>. They obey Ω² = GM/r³ and dτ/dt = √(1 − 3r<sub>g</sub>/r). Moving an orbit slider arbitrarily close to the horizon therefore describes a prescribed visual path, not a stable relativistic orbit. The distant black-hole shadow has critical impact parameter 3√3 r<sub>g</sub>; its visible rim is not the event-horizon surface at 2r<sub>g</sub>.</p><button class="outline-button" data-relativity-target="blackholes">Continue to black holes ↗</button>')+
 part('10','Kerr: allow the source to rotate',
 '<p>For an isolated, stationary, uncharged rotating black hole, axial symmetry replaces spherical symmetry. The Kerr solution contains mass M and angular momentum J. Define a = J/(Mc), χ = a/r<sub>g</sub>, Σ = r² + a²cos²θ, and Δ = r² − 2r<sub>g</sub>r + a². In Boyer–Lindquist coordinates:</p>'+eq(kerr,'Kerr metric in SI units with radial spin length a')+
 eq(R(S(r,O('±')),equal,rg,O('±'),Q(R(sq(rg),minus,sq(a))),equal,rg,B(R(N(1),O('±'),Q(R(N(1),minus,sq(I('χ'))))))),'Kerr coordinate horizon radii')+
 '<p>The dt dφ term is the signature of frame dragging in these coordinates. The outer event horizon is r₊; r₋ is the ideal inner Cauchy horizon. The ergosurface, where stationary observers cease to be possible, is distinct from r₊ away from the axis. The ring singularity has Σ = 0. Setting a = 0 returns Schwarzschild. These formulas apply to the ideal subextremal solution |χ| &lt; 1; the app’s spin control remains below extremality.</p>'+
 '<p>Clock comparisons near a rotating hole depend on latitude and the observer’s angular motion. Substituting a Kerr horizon radius into a Schwarzschild clock formula is only a proxy. The existing notebook separates the exact metric from the renderer’s bounded-cost approximation.</p>')+
 part('11','Alcubierre: prescribe a moving shift',
 '<p>A 3+1 split describes spatial geometry γ<sub>ij</sub>, lapse α, and dimensionless shift β<sup>i</sup>. It is a way to write a metric, not a new gravity law:</p>'+eq(R(sq(D(I('s'))),equal,minus,sq(I('α')),sq(c),sq(D(t)),plus,S(I('γ'),R(I('i'),I('j'))),B(R(D(X('i')),plus,P(beta,I('i')),c,D(t))),B(R(D(X('j')),plus,P(beta,I('j')),c,D(t)))),'ADM metric with dimensionless shift and x-zero equals ct')+
 '<p>Alcubierre chooses α = 1, γ<sub>ij</sub> = δ<sub>ij</sub>, and β = −v<sub>s</sub>(t)f(r<sub>s</sub>)/c around a prescribed center x<sub>s</sub>(t):</p>'+eq(row(R(sq(D(I('s'))),equal,minus,sq(c),sq(D(t)),plus,sq(B(R(D(V('x')),minus,I('f'),B(S(r,I('s'))),S(V('v'),I('s')),D(t))))),R(S(r,I('s')),equal,O('|'),V('x'),minus,S(V('x'),I('s')),B(t),O('|'),O(','),T('   '),S(V('v'),I('s')),equal,F(D(S(V('x'),I('s'))),D(t))),shape),'Alcubierre vector-shift metric and smooth finite wall profile')+
 '<p>The squared vector bracket denotes its Euclidean squared norm. Here r<sub>s</sub> means distance from the ship center, not the Schwarzschild radius. R is bubble radius and σ has inverse-length units. At the center f = 1 and dx = v<sub>s</sub>dt, so dτ = dt. Spatial slices are intrinsically flat, yet spacetime curvature can be nonzero because the shift varies. This does not prove a realizable propulsion mechanism: the required stress-energy is exotic, and causal control and stability are unresolved.</p>'+
 '<p>The exact metric does not supply Star Trek warp factors, a power plant, or permission simply to add a black-hole metric. The live scene uses compressed optical effects and illustrative grids; it does not numerically solve the full combined Einstein equations.</p><button class="outline-button" data-relativity-target="warp">Continue to warp metrics ↗</button>')+
 part('12','Ellis: a different spatial topology',
 '<p>The traversable comparison uses proper radial coordinate ℓ, ranging from one asymptotic end to the other, and minimum areal radius b &gt; 0:</p>'+eq(R(sq(D(I('s'))),equal,minus,sq(c),sq(D(t)),plus,sq(D(I('ℓ'))),plus,B(R(sq(I('ℓ')),plus,sq(I('b')))),B(R(sq(D(theta)),plus,trig2('sin',theta),sq(D(az))))),'Ultrastatic Ellis wormhole metric')+
 '<p>The throat is at ℓ = 0 with area 4πb². Because g<sub>tt</sub> = −c² everywhere, stationary clocks have no gravitational time difference between the ends; local motion still adds special-relativistic dilation. Spatial curvature can lens light even though this time coefficient is constant. The model requires exotic stress-energy.</p>'+
 '<p>The historical Einstein–Rosen bridge in the maximal Schwarzschild extension is not a traversable shortcut. It must not be identified with the Ellis throat used for the crossings here. Opening a portal, inserting planets, or carrying another black hole through it is a visual composition rather than a solved dynamical spacetime.</p><button class="outline-button" data-relativity-target="wormholes">Continue to wormholes ↗</button>')+
 '<section class="relativity-reading"><h3>The path in one line</h3><p><strong>Local measurements → invariant interval → metric → connection → curvature → field equations → chosen solution → clocks and light paths.</strong> Symmetries and boundary conditions choose the solution; observer worldlines choose the measured clock rates and images.</p><p>This is a compact development of the ingredients used by the observatory, not a replacement for a full course. The separate notebooks give the scene-specific formulas, diagrams, and approximation limits.</p><h4>Primary references and further study</h4><ul class="sources"><li>'+link('https://www.damtp.cam.ac.uk/user/tong/relativity/seven.pdf','David Tong: Special Relativity')+' — transformations, clocks, and relativistic dynamics.</li><li>'+link('https://www.damtp.cam.ac.uk/user/tong/gr/grhtml/S1.html','Tong: Geodesics in Spacetime')+'; '+link('https://www.damtp.cam.ac.uk/user/tong/gr/grhtml/S3.html','Riemannian Geometry')+'; '+link('https://www.damtp.cam.ac.uk/user/tong/gr/grhtml/S4.html','The Einstein Equations')+'; '+link('https://www.damtp.cam.ac.uk/user/tong/gr/grhtml/S6.html','Black Holes')+'.</li><li>'+link('https://arxiv.org/abs/gr-qc/0009013','Alcubierre (1994): The warp drive')+' — the original metric construction.</li><li>'+link('https://arxiv.org/abs/1607.07022','Tsukamoto (2016): Gravitational lensing of an Ellis wormhole')+' — the ultrastatic comparison and lensing.</li></ul><p class="math-note">All equations and diagrams are included locally. Reference links are optional and require internet access only when opened.</p></section></div>';
}
